import zlib
import base64
import numpy as np

SHADING_DENSITY_B64 = ""

def get_tone_density_map():
    raw = base64.b64decode(SHADING_DENSITY_B64)
    u8 = np.frombuffer(zlib.decompress(raw), dtype=np.uint8).reshape((128, 128))
    return u8.astype(np.float32) / 255.0

